Definition art_post_writtenG (sp t c ab rz n rs a : Z) : Prop :=
  (sp - 1952 <= a < sp) \/ (ab <= a < ab + rz + n) \/ (2147450880 + (ab + rz) / 8 <= a < 2147450880 + (ab + rz) / 8 + rs / 8)
  \/ (t + 2800 <= a < t + 2824) \/ (t + 2912 + 8 * c <= a < t + 2920 + 8 * c).

