Lemma cell_e_size : forall M sp ab rz n b1 u, 32 <= sp -> sp < 2 ^ 64 -> 0 <= ab -> ab + rz < 2 ^ 64 -> (rz = 16 \/ 32 <= rz) ->
  apart (sp - 32) 32 (ab + rz - 12) 4 -> cellA M (ab + rz - 12) 4 u -> cellA (art_e_mem M sp ab rz n b1) (ab + rz - 12) 4 u.
Proof.
  intros M sp ab rz n b1 u Hsp Hsp' Hab Hab' Hrz A C. unfold art_e_mem. unfold apart in A.
  destruct (Z.eqb_spec rz 16); repeat (apply cell_Wn_other; [lia|cbn; lia|lia|cbn; lia|unfold apart; cbn; lia|]); exact C.
Qed.

Lemma nor5 : forall A B C D E : Prop, ~ (A \/ B \/ C \/ D \/ E) -> ~ A /\ ~ B /\ ~ C /\ ~ D /\ ~ E.
Proof. intros A B C D E H. repeat split; intro; apply H; tauto. Qed.

